<script setup>
import {formatMXN} from '~~/shared/features/pricing/prices.js'
const {data:cart,error,refresh}=await useFetch('/api/cart')
const {data:shipping}=await useFetch('/api/shipping/selected')
const email=ref(''),accepted=ref(false),busy=ref(false),failure=ref(''),order=ref(null),key=ref('')
const address=reactive({recipientName:'',phone:'',postalCode:'',state:'',city:'',district:'',street:'',exteriorNumber:'',interiorNumber:''})
const total=computed(()=>cart.value?.totals&&shipping.value?.selected?(BigInt(cart.value.totals.goodsMoneyCents)+BigInt(shipping.value.selected.chargedAmountCents)).toString():null)
onMounted(()=>{key.value=crypto.randomUUID();const d=shipping.value?.selected?.destination;if(d)Object.assign(address,{recipientName:d.name,phone:d.phone,postalCode:d.postalCode,state:d.state,city:d.city,street:d.street})})
async function prepare(){if(busy.value)return;busy.value=true;failure.value='';try{order.value=await $fetch('/api/checkout/prepare',{method:'POST',body:{email:email.value,address:{...address},accepted:accepted.value,quoteId:shipping.value.selected.id,cartVersion:cart.value.version,expectedTotalCents:total.value,idempotencyKey:key.value}})}catch(e){failure.value=e.data?.statusMessage??'No pudimos preparar tu pedido.'}finally{busy.value=false}}
</script>
<template><section class="mx-auto max-w-store px-4 py-12 md:px-8"><UiBreadcrumbs :items="[{label:'Carrito',to:'/carrito'},{label:'Preparar pedido'}]"/><h1 class="text-display-l font-bold">Preparar pedido</h1><p class="mt-4 text-ink-2">El pago está pendiente de habilitar. Preparar un pedido conserva el carrito y no reserva existencias ni completa una compra.</p><div v-if="error" role="alert" class="mt-4"><p>Carrito no disponible.</p><UiButton @click="refresh">Reintentar</UiButton></div><p v-if="failure" role="alert" class="mt-4 text-crit">{{failure}}</p><div v-if="order" class="mt-6" role="status"><p>Pedido preparado: {{order.number}}</p><p>{{formatMXN(order.totalMoneyCents)}} {{order.currency}} · Pendiente de pago, sin reserva.</p><NuxtLink to="/pedidos" class="inline-flex min-h-11 items-center text-accent-text underline">Consultar pedidos de mi cuenta</NuxtLink></div><p v-else-if="!cart?.lines.length||!shipping?.selected" class="mt-6">Agrega productos y cotiza/acepta el envío en el carrito para continuar.</p><form v-else class="mt-6 grid max-w-xl gap-4" @submit.prevent="prepare"><p class="font-mono">Importe actual con envío: {{formatMXN(total)}} MXN</p><UiField id="checkout-email" v-model="email" label="Correo de compra" type="email" required maxlength="254"/><UiField v-for="field in [{key:'recipientName',label:'Destinatario'},{key:'phone',label:'Teléfono'},{key:'postalCode',label:'Código postal'},{key:'state',label:'Código estatal Envia.com (dos letras)'},{key:'city',label:'Ciudad'},{key:'district',label:'Colonia'},{key:'street',label:'Calle completa igual a la cotización (incluye número)'},{key:'exteriorNumber',label:'Número exterior'},{key:'interiorNumber',label:'Número interior (opcional)'}]" :id="`checkout-${field.key}`" :key="field.key" v-model="address[field.key]" :label="field.label" :required="field.key!=='interiorNumber'" maxlength="200"/><p class="text-body-s">Si cambias la dirección, vuelve al carrito para cotizar y aceptar la tarifa correspondiente.</p><div class="flex flex-wrap gap-4"><NuxtLink v-for="slug in ['privacidad','terminos','devoluciones']" :key="slug" :to="`/politicas/${slug}`" class="inline-flex min-h-11 items-center text-accent-text underline">{{slug}}</NuxtLink></div><label class="flex min-h-11 items-center gap-3"><input v-model="accepted" type="checkbox" required>Acepto las políticas publicadas y el importe mostrado para preparar el pedido.</label><UiButton type="submit" :disabled="busy||!accepted">{{busy?'Preparando…':'Preparar sin cobrar'}}</UiButton></form><NuxtLink to="/carrito" class="mt-6 inline-flex min-h-11 items-center text-accent-text underline">Volver al carrito</NuxtLink></section></template>
